      <EditorHistoryTree open={treeOpen} revealVersion={treeReveal} session={session} draft={draft} browseId={treeBrowseId} previewId={help.open?null:treePreviewId} pair={comparePair} busy={documentBusy} comparison={help.open?null:comparison} compareViewport={compareViewport} setCompareViewport={setCompareViewport} onBrowse={chooseHistory} onOpen={openTreePreview} onTake={takeTreeFrame} onClose={closeTree} onClosePreview={()=>setTreePreviewId(null)} onCloseCompare={()=>setComparison(null)} onVisibility={(id,hidden)=>void libraryAction(hidden?'restoreStep':'deleteStep',id).catch(()=>{})}/>
