    {exportOpen?<EditorModal title={localeText("editor", "ui.EditorWindow.d28e495446ce695c")} busy={localBusy} onClose={()=>setExportOpen(false)}><Hint message={{id:"project.export-format"}}><label className="editor-inline-field">{localeText("editor", "ui.EditorWindow.62235e3ecc1497d8")}<select aria-label={localeText("editor", "ui.EditorWindow.1236ee0aa97cb72b")} value={exportFormat} onChange={e=>setExportFormat(e.target.value)}><option value="png">{localeText("editor", "ui.EditorWindow.dfd1858d8c4e9c71")}</option><option value="jpeg">{localeText("editor", "ui.EditorWindow.737a1f6ec13a9569")}</option><option value="tiff">{localeText("editor", "ui.EditorWindow.52c01285296fd3dc")}</option><option value="bmp">{localeText("editor", "ui.EditorWindow.a23e3798dc23292f")}</option></select></label></Hint>{exportFormat==='jpeg'?<Hint message={{id:"project.jpeg-quality"}}><label className="editor-inline-field">{localeText("editor", "ui.EditorWindow.6f9982762cd4949a")}<input aria-label={localeText("editor", "ui.EditorWindow.c20c0adccf0d4f5c")} type="number" min={1} max={100} value={exportQuality} onChange={e=>setExportQuality(Number(e.target.value))}/></label></Hint>:null}<Hint message={{id:"project.storage-default"}}><label className="editor-inline-field"><input type="checkbox" checked={useStorageDefault} onChange={e=>setUseStorageDefault(e.target.checked)}/>{localeText("editor", "ui.EditorWindow.3de4fce39e1c4921")}</label></Hint><Hint message={{id:"project.publish-archive"}}><label className="editor-inline-field"><input type="checkbox" checked={publishToArchive} onChange={e=>setPublishToArchive(e.target.checked)}/>{localeText("editor", "ui.EditorWindow.ebee2994450eab7f")}</label></Hint><p className="editor-muted">{localeText("editor", "ui.EditorWindow.88e8078428c75618")}</p><Hint message={{id:useStorageDefault&&!publishToArchive?'project.export-copy':'project.choose-save'}}><button type="button" disabled={localBusy} className="editor-primary" onClick={()=>void exportImage()}>{useStorageDefault&&!publishToArchive?localeText("editor", "ui.EditorWindow.e5740e9afb265044"):localeText("editor", "ui.EditorWindow.5d70dafca8c575bc")}</button></Hint></EditorModal>:null}


